//! Color Hurry core for the native shells.
//!
//! `CoreFfi` wraps the Crux bridge: events, effect requests and the view model
//! cross the boundary as bincode bytes, and the Swift / Kotlin types for them
//! are generated by `codegen`. The two advertisement helpers keep the BLE wire
//! format in Rust, so the shells never parse or build payloads themselves.

use color_hurry_core::{decode_color, encode_color, Color, ColorHurry, Event, COMPANY_ID};
use crux_core::{
    bridge::{Bridge, EffectId},
    Core,
};

/// The main interface used by the shells.
pub struct CoreFfi {
    core: Bridge<ColorHurry>,
}

impl Default for CoreFfi {
    fn default() -> Self {
        Self::new()
    }
}

#[boltffi::export]
impl CoreFfi {
    #[must_use]
    pub fn new() -> Self {
        Self {
            core: Bridge::new(Core::new()),
        }
    }

    /// Send a serialized `Event` to the app and return the serialized requests.
    /// # Panics
    /// If the event cannot be deserialized.
    #[must_use]
    pub fn update(&self, data: &[u8]) -> Vec<u8> {
        let mut effects = Vec::new();
        match self.core.update(data, &mut effects) {
            Ok(()) => effects,
            Err(e) => panic!("{e}"),
        }
    }

    /// Resolve the request `id` with serialized output and return new requests.
    /// # Panics
    /// If the output cannot be deserialized or the `id` is unknown.
    #[must_use]
    pub fn resolve(&self, id: u32, data: &[u8]) -> Vec<u8> {
        let mut effects = Vec::new();
        match self.core.resolve(EffectId(id), data, &mut effects) {
            Ok(()) => effects,
            Err(e) => panic!("{e}"),
        }
    }

    /// The current serialized `ViewModel`.
    /// # Panics
    /// If the view model cannot be serialized.
    #[must_use]
    pub fn view(&self) -> Vec<u8> {
        let mut view_model = Vec::new();
        match self.core.view(&mut view_model) {
            Ok(()) => view_model,
            Err(e) => panic!("{e}"),
        }
    }
}

/// Bluetooth company ID the Color Hurry manufacturer data is filed under.
#[boltffi::export]
#[must_use]
pub fn color_company_id() -> u16 {
    COMPANY_ID
}

/// Turn a scanned manufacturer payload (after the company ID) into a serialized
/// `Event::ColorReceived`, or an empty buffer if it is not a Color Hurry ad.
#[boltffi::export]
#[must_use]
pub fn color_received_event(payload: &[u8]) -> Vec<u8> {
    decode_color(payload)
        .map(|(channel, color)| {
            bincode::serialize(&Event::ColorReceived { channel, color }).unwrap_or_default()
        })
        .unwrap_or_default()
}

/// Build the manufacturer payload (after the company ID) for a serialized
/// `Color` on `channel`, or an empty buffer if either is out of range.
#[boltffi::export]
#[must_use]
pub fn color_advertisement(channel: u8, color: &[u8]) -> Vec<u8> {
    bincode::deserialize::<Color>(color)
        .ok()
        .and_then(|color| encode_color(channel, color))
        .map(|payload| payload.to_vec())
        .unwrap_or_default()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn advertisement_roundtrip() {
        let color = bincode::serialize(&Color::Orange).unwrap();
        let payload = color_advertisement(2, &color);
        assert_eq!(payload, [b'S', 4, 3, 2, 2]);
        let event: Event = bincode::deserialize(&color_received_event(&payload)).unwrap();
        assert_eq!(
            event,
            Event::ColorReceived {
                channel: 2,
                color: Color::Orange
            }
        );
    }

    #[test]
    fn rejects_foreign_payload() {
        assert!(color_received_event(&[b'X', 4, 3, 0, 1]).is_empty());
        assert!(color_advertisement(9, &bincode::serialize(&Color::Red).unwrap()).is_empty());
    }
}
